<template><section><h2>我的事件跟踪</h2><el-alert v-if="error" :title="error" type="warning"/><template v-else-if="summary"><div class="summary"><el-button v-for="(label,key) in labels" :key="key" link @click="openTracking()"><strong>{{summary[key]}}</strong> {{label}}</el-button></div><p v-for="item in summary.items" :key="item.id"><el-button link @click="openTracking(item.id)">{{item.title}} · {{states[item.status]}}</el-button></p><el-empty v-if="!summary.items.length" description="暂无跟踪事项"/></template><p v-else>正在加载跟踪事项…</p></section></template>
<script setup>import {ref,onMounted,onBeforeUnmount} from 'vue';import {tracking,states} from '../../api/issueTracking';function openTracking(issueId=''){window.dispatchEvent(new CustomEvent('open-event-tracking',{detail:{issueId}}));}const summary=ref(null),error=ref(''),labels={pending:'待办理',processing:'办理中',confirming:'待确认',overdue:'办理逾期'};async function load(){try{summary.value=await tracking('summary/');error.value='';}catch(e){error.value=e.message;}}onMounted(()=>{load();window.addEventListener('issue-tracking-updated',load);});onBeforeUnmount(()=>window.removeEventListener('issue-tracking-updated',load));</script><style scoped>.summary{display:flex;gap:24px;flex-wrap:wrap}.summary strong{font-size:24px}</style>
